parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "cause": {
      "type": "string",
      "enum": [
        "timing_difference",
        "bank_fee_or_charge",
        "fx_difference",
        "duplicate_posting",
        "missing_ledger_posting",
        "keying_error",
        "unknown"
      ],
      "description": "Cause established from the items."
    },
    "proposal": {
      "type": "string",
      "enum": [
        "match_only",
        "post_entries",
        "no_action",
        "refer"
      ],
      "description": "What to do."
    },
    "break_amount": {
      "type": "number",
      "description": "Break amount you computed from the items: statement minus ledger."
    },
    "matches": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "ledger_item_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Ledger item ids."
          },
          "statement_item_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Statement item ids."
          }
        },
        "required": [
          "ledger_item_ids",
          "statement_item_ids"
        ],
        "additionalProperties": false
      },
      "description": "Match groups covering every item on the break."
    },
    "entries": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "gl_account": {
            "type": "string",
            "description": "Account to post to."
          },
          "debit": {
            "type": "number",
            "description": "Debit amount, 0 if this is a credit line."
          },
          "credit": {
            "type": "number",
            "description": "Credit amount, 0 if this is a debit line."
          },
          "reference": {
            "type": "string",
            "description": "Reference that ties the line to the break, for example the bank reference."
          }
        },
        "required": [
          "gl_account",
          "debit",
          "credit",
          "reference"
        ],
        "additionalProperties": false
      },
      "description": "Adjusting entries. Empty unless post_entries."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "cause",
    "proposal",
    "break_amount",
    "matches",
    "entries",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Reconciliation agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize break').item.json;
const b = $json; // fresh read of the break with its items and posting rules
const p = out?.proposal;
const r2 = (v) => Math.round(v * 100) / 100;
const items = b.items ?? [];
const sideOf = Object.fromEntries(items.map((x) => [String(x.id), x.side]));
const amountOf = Object.fromEntries(items.map((x) => [String(x.id), Number(x.amount)]));
const sum = (ids) => r2(ids.reduce((s, id) => s + (amountOf[id] ?? 0), 0));
const stmtIds = items.filter((x) => x.side === 'statement').map((x) => String(x.id));
const ledgerIds = items.filter((x) => x.side === 'ledger').map((x) => String(x.id));
const breakAmount = r2(sum(stmtIds) - sum(ledgerIds));
const matches = out?.matches ?? [];
const entries = out?.entries ?? [];
const allowed = new Set([...(b.rules?.allowed_accounts ?? []), req.ledger_account].map(String));
const totalDr = r2(entries.reduce((s, e) => s + Number(e.debit ?? 0), 0));
const totalCr = r2(entries.reduce((s, e) => s + Number(e.credit ?? 0), 0));
const net = r2(entries.filter((e) => String(e.gl_account) === req.ledger_account).reduce((s, e) => s + Number(e.debit ?? 0) - Number(e.credit ?? 0), 0));
const ageDays = req.value_date ? Math.floor((Date.now() - Date.parse(req.value_date)) / 86400000) : Infinity;
const noop = p === 'no_action' && out?.cause === 'timing_difference' && ageDays <= cfg.max_timing_days;

if (b.status !== 'open') reasons.push('break status is now ' + b.status);
if (b.currency && b.currency !== req.currency) reasons.push('break currency on record ' + b.currency + ' differs from the event ' + req.currency);
if (Math.abs(breakAmount - req.break_amount) > 0.005) reasons.push('items on record give a break of ' + breakAmount + ', the event said ' + req.break_amount);
if (out && Math.abs(Number(out.break_amount) - breakAmount) > 0.005) reasons.push('agent break amount ' + out.break_amount + ' differs from recomputed ' + breakAmount);
if (p === 'refer') reasons.push('agent could not explain the break');
if (p === 'no_action' && !noop) reasons.push(out?.cause !== 'timing_difference' ? 'no action proposed for a break that is not a timing difference' : 'timing difference is ' + ageDays + ' days old (limit ' + cfg.max_timing_days + ')');

if (p === 'match_only' || p === 'post_entries') {
  if (b.rules?.period_status !== 'open') reasons.push('accounting period is ' + (b.rules?.period_status ?? 'unknown'));
  const used = matches.flatMap((m) => [...(m.ledger_item_ids ?? []), ...(m.statement_item_ids ?? [])].map(String));
  const unknown = used.filter((id) => !(id in sideOf));
  const dup = used.filter((id, k) => used.indexOf(id) !== k);
  const left = items.map((x) => String(x.id)).filter((id) => !used.includes(id));
  const wrongSide = matches.flatMap((m) => [...(m.ledger_item_ids ?? []).filter((id) => sideOf[id] && sideOf[id] !== 'ledger'), ...(m.statement_item_ids ?? []).filter((id) => sideOf[id] && sideOf[id] !== 'statement')]);
  if (unknown.length) reasons.push('matches cite items not on this break: ' + unknown.join(', '));
  if (dup.length) reasons.push('items used in more than one match: ' + [...new Set(dup)].join(', '));
  if (left.length) reasons.push('items left unmatched: ' + left.join(', '));
  if (wrongSide.length) reasons.push('items placed on the wrong side of a match: ' + wrongSide.join(', '));
}
if (p === 'match_only') {
  if (entries.length) reasons.push('match only proposed with adjusting entries');
  if (Math.abs(breakAmount) > 0.005) reasons.push('match only cannot clear a break of ' + breakAmount);
}
if (p === 'post_entries') {
  if (!entries.length) reasons.push('post entries proposed with no entries');
  if (entries.length > cfg.max_entry_lines) reasons.push(entries.length + ' entry lines exceeds ' + cfg.max_entry_lines);
  for (const e of entries) {
    const dr = Number(e.debit ?? 0);
    const cr = Number(e.credit ?? 0);
    if (dr < 0 || cr < 0 || (dr > 0) === (cr > 0)) reasons.push('line on ' + e.gl_account + ' must have exactly one positive side');
    if (!allowed.has(String(e.gl_account))) reasons.push('account ' + e.gl_account + ' is not on the allowed list for ' + req.recon_id);
    if ((cfg.suspense_accounts ?? []).map(String).includes(String(e.gl_account))) reasons.push('entries post to suspense account ' + e.gl_account);
  }
  if (totalDr !== totalCr) reasons.push('entries do not balance: debits ' + totalDr + ', credits ' + totalCr);
  if (Math.abs(net - breakAmount) > 0.005) reasons.push('entries move ledger account ' + req.ledger_account + ' by ' + net + ', the break is ' + breakAmount);
  if (totalDr > cfg.max_adjustment_amount) reasons.push('adjustment of ' + totalDr + ' above ' + cfg.max_adjustment_amount + ' goes to the controller');
}

const action = {
  type: p,
  break_id: req.break_id,
  recon_id: req.recon_id,
  currency: req.currency,
  value_date: req.value_date,
  cause: out?.cause ?? null,
  matches,
  entries: entries.map((e) => ({ gl_account: String(e.gl_account), debit: Number(e.debit ?? 0), credit: Number(e.credit ?? 0), reference: String(e.reference ?? '').slice(0, 60) })),
  net_amount: net,
};
const summary = 'Break ' + req.break_id + ' on ' + req.recon_id + ' · ' + breakAmount + ' ' + req.currency + ' · cause ' + (out?.cause ?? 'unknown') + '.\n'
  + 'Proposed: *' + p + '* · ' + matches.length + ' match groups'
  + (entries.length ? ' · ' + entries.length + ' entry lines, debits ' + totalDr + ' = credits ' + totalCr + ', net ' + net + ' on ' + req.ledger_account : '') + '.\n'
  + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const lines = Number($json.journal?.line_count ?? 0);
const ok = $json.status === 'resolved' && Math.abs(Number($json.residual_amount ?? NaN)) < 0.005 && lines === planned.entries.length;
const detail = 'break shows status ' + $json.status + ', residual ' + $json.residual_amount + ', ' + lines + ' journal lines; expected resolved, 0, ' + planned.entries.length + ' lines';
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize break').item.json;
let agent = null;
let guard = null;
try { agent = $('Reconciliation agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "reconciliation operations",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Break ' + intake.break_id + ' · ' + intake.recon_id + ' · ' + intake.break_amount + ' ' + intake.currency + ' · proposed ' + (agent?.output?.proposal ?? 'none'),
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

parameters.jsCode:
const intake = $('Normalize break').item.json;
let agent = null;
let guard = null;
let approval = null;
try { agent = $('Reconciliation agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}
// Present only on workflows with a named-approver step, and only if this run reached it.
try { approval = $('Record approval').item.json; } catch (e) {}

return {
  json: {
    business_key: intake.business_key,
    outcome: $json.outcome,
    approval: approval ? { decision: approval.decision, approver: approval.approver, decided_at: approval.decided_at } : null,
    route: guard?.route ?? 'escalate',
    decision: agent?.output ?? null,
    guardrail_reasons: guard?.guardrail_reasons ?? [],
    actions: guard?.planned_actions ?? [],
    tool_calls: (agent?.intermediateSteps ?? []).length,
  },
};
